\caption{One-Step Estimator.}
\label{alg:one_step_estim}
\begin{algorithmic}
\STATE {\bfseries Input:} observation $\bY$ and sensing matrix $\bX$.
\STATE {\bfseries Output:} pair $(\bPi^{\opt},~\bB^{\opt})$, which
is written as
\begin{align}
\label{eq:optim_estim_pi}
\bPi^{\opt} &= \argmax_{\bPi \in \calP_n} \
\La \bPi, \bY\bY^{\rmt}\bX\bX^{\rmt}\Ra, \\
\bB^{\opt} &= \bX^{\dagger} \wh{\bPi}^{\rmt}\bY,
\label{eq:optim_estim_B}
\end{align}
where $\bX^{\dagger} = (\bX^{\rmt}\bX)^{-1}\bX^{\rmt}$ denotes the pseudo-inverse of
$\bX$ (Section~$5.5.2$ in~\citet{golub2012matrix}) and
$\calP_n$ is the set of all possible permutation matrices.
\end{algorithmic}

\begin{align}
\label{eq:optim_estim_pi}
\bPi^{\opt} &= \argmax_{\bPi \in \calP_n} \
\La \bPi, \bY\bY^{\rmt}\bX\bX^{\rmt}\Ra, \\
\bB^{\opt} &= \bX^{\dagger} \wh{\bPi}^{\rmt}\bY,
\label{eq:optim_estim_B}
\end{align}

\begin{align}
\label{eq:one_step_oracle}
\bPi^{\opt} = \argmax_{\bPi\in \calP_n} \La \bPi, \bY (\nfrac{\bB^{\natural \rmt}}{\alpha})\bX^{\rmt}\Ra,
\end{align}

