\label{lemma:xpix_proximity}
We have $\Prob\bracket{\calE_1}\geq 1-  c_0 e^{-c_1 n}$ when
$n$ is sufficiently large, where $c_0, c_1 > 0$ are some positive constants.

\begin{align}
\label{eq:xpix_proximity_tot}
& \Prob\bracket{\langle \bx, \bPi^{\natural}\bx \rangle \leq c_0 n} \stackrel{\cirone}{\leq} \
\underbrace{\Prob\bracket{\sum_{i=1}^h x_i x_{\pi^{\natural}(i)} \leq  -\frac{c_0 n}{2} }}_{\defequal~\zeta_1} +
\underbrace{\Prob\bracket{\sum_{i=h+1}^n x_i^2 \leq \frac{3c_0 n}{2}}}_{\defequal~\zeta_2}.
\end{align}

\begin{align}
\label{eq:xpix_proximity_zetaone}
\zeta_1 \leq~& \sum_{\ell=1}^3 \Prob\bigg(\sum_{i\in \calI_{\ell}}x_i x_{\pi^{\natural}(i)}\leq \frac{-c_0 n}{6}\bigg)
\leq  \sum_{\ell=1}^3 \Prob\bigg(\bigg|\sum_{i\in \calI_{\ell}}x_i x_{\pi^{\natural}(i)}\bigg|\geq c_1 n\bigg).
\end{align}

\begin{align}
\label{eq:xpix_proximity_zetatwo}
\zeta_2\leq~&
\Prob\bracket{\abs{\sum_{i=h+1}^n x_i^2 - (n-h)} \geq \frac{n-h}{2}}
\stackrel{\cirfour}{\leq}
\exp\Bracket{-c_0\bracket{\frac{n-h}{\opnorm{\bI_{(n-h)\times (n-h)}}}\vcap \frac{(n-h)^2}{\fnorm{\bI_{(n-h)\times (n-h)}}^2}}} \notag \\
\stackrel{\cirfive}{=}~& e^{-cn},
\end{align}

