\label{lemma:small_ball_subgauss}
Let $\bg \in \RR^n$ be a random vector with
each entry to be independent sub-gaussian RV with
$\Var(g_i) \geq 1$ and sub-gaussian constants
bounded by $K$, and $\bA$ is a non-zero
$n\times n$ matrix. For any $\by\in \RR^n$ and
$\varepsilon\in (0, c_1)$, one has
\begin{align*}
\Prob\bracket{\norm{\by - \bA\bg}{2} \leq \nfrac{1}{2}\fnorm{\bA}}
\leq 2\exp\bracket{-\frac{c_0}{K^4}\srank{\bA} }.
\end{align*}

\begin{align*}
\Prob\bracket{\norm{\by - \bA\bg}{2} \leq \nfrac{1}{2}\fnorm{\bA}}
\leq 2\exp\bracket{-\frac{c_0}{K^4}\srank{\bA} }.
\end{align*}

\label{lemma:small_ball_log_concave}
Let $\bg \in \RR^n$ be an isotropic log-concave random vector
with sub-gaussian constant $K$, and $\bA$ is a non-zero
$n\times n$ matrix. For any $\by\in \RR^n$ and
$\varepsilon\in (0, c_1)$, one has
\begin{align*}
\Prob\bracket{\norm{\by - \bA\bg}{2} \leq \varepsilon \fnorm{\bA}}
\leq \exp\bracket{\kappa(K)\srank{\bA}\log \varepsilon },
\end{align*}
where $\kappa = c_1/K^2$.

\begin{align*}
\Prob\bracket{\norm{\by - \bA\bg}{2} \leq \varepsilon \fnorm{\bA}}
\leq \exp\bracket{\kappa(K)\srank{\bA}\log \varepsilon },
\end{align*}
